import sys

def max_accordion_length(s):
    max_length = -1
    current_start = -1
    current_length = 0

    for i, char in enumerate(s):
        if char == '[':
            current_start = i
            current_length = 0
        elif char == '|':
            if current_start != -1:
                current_length += 1
        elif char == ']':
            if current_start != -1:
                max_length = max(max_length, 2 + current_length)
                current_start = -1
                current_length = 0

    return max_length

